  if (!MaybeComponent) {
    return createTransportNode(
      ctx,
      transportSegment,
      prefetchHints,
      createElement(
        Fragment,
        {
          key: cacheNodeKey,
        },
        layerAssets,
        parallelRouteProps.children
      ),
      parallelRouteNodes,
      loadingData,
      isPossiblyPartialResponse,

      // No user-provided component, so no params will be accessed. Use the
      // pre-resolved empty tracker.
      emptyVaryParamsAccumulator
